
-- All Female demographic product and their price, sale, stock and revenue. 

SELECT product, price, sales, stock_levels, rev_gen FROM supply_chain
WHERE gender = 'Female'
ORDER BY rev_gen DESC;


-- Top 10 Revenue generated by female targeted products. 

SELECT product, price, sales, stock_levels, rev_gen FROM supply_chain
WHERE gender = 'Female'
ORDER BY rev_gen DESC LIMIT 10;



-- All Male demographic product and their price, sale, stock and revenue. 

SELECT product, price, sales, stock_levels, rev_gen FROM supply_chain
