-- All Non-binary demographic product and their price, sale, stock and revenue. 

SELECT product, price, sales, stock_levels, rev_gen FROM supply_chain
WHERE gender = 'Non-binary'
ORDER BY rev_gen DESC;


-- Top 10 Revenue generated by Non-binary targeted products. 

SELECT product, price, sales, stock_levels, rev_gen FROM supply_chain
WHERE gender = 'Non-binary'
